    13	/**
    14	 * A way of selling a stay. Each plan brings its own rules: who may use it ({@link #validate}), how the
    15	 * stay is priced ({@link #price}) and what comes back when a reservation is cancelled ({@link #refund}).
    16	 * A new plan is a new constant here (and a value in the database column, which is plain text).
    17	 */
    18	public enum RatePlan {
    19	    /** Full price; the guest gets everything back when cancelling a confirmed reservation. */
    20	    STANDARD {
    21	        @Override
    22	        Price price(PriceCalculator calculator, Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    23	            return discounted(calculator, room, checkIn, checkOut, BigDecimal.ZERO);
    24	        }
    25	
    26	        @Override
    27	        BigDecimal refund(BigDecimal amountPaid) {
    28	            return amountPaid;
    29	        }
    30	    },
    31	    /** 15% off, but nothing comes back on cancellation. */
    32	    NON_REFUNDABLE {
    33	        @Override
    34	        Price price(PriceCalculator calculator, Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    35	            return discounted(calculator, room, checkIn, checkOut, new BigDecimal("0.15"));
    36	        }
    37	
    38	        @Override
    39	        BigDecimal refund(BigDecimal amountPaid) {
    40	            return cents(BigDecimal.ZERO);
    41	        }
    42	    },
    43	    /** Agreement with a company: its discount on the nights, identified by the company code. Full refund. */
    44	    CORPORATE {
    45	        private final Map<String, BigDecimal> agreements = Map.of(
    46	                "TECNOSUL", new BigDecimal("0.12"),
    47	                "AGROVALE", new BigDecimal("0.18"),
    48	                "FARMAVIDA", new BigDecimal("0.25"));
    49	
    50	        @Override
    51	        void validate(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    52	            if (companyCode == null || !agreements.containsKey(companyCode)) {
    53	                throw invalid("the corporate rate needs the code of a company with an agreement");
    54	            }
    55	        }
    56	
    57	        @Override
    58	        Price price(PriceCalculator calculator, Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    59	            return discounted(calculator, room, checkIn, checkOut, agreements.get(companyCode));
    60	        }
    61	
    62	        @Override
    63	        BigDecimal refund(BigDecimal amountPaid) {
    64	            return amountPaid;
    65	        }
    66	    },
    67	    /** Friday to Sunday (two nights) for a fixed price all year round, with no discount. Half comes back. */
    68	    WEEKEND_PACKAGE {
    69	        private final Map<RoomType, BigDecimal> prices = Map.of(
    70	                RoomType.STANDARD, new BigDecimal("520.00"),
    71	                RoomType.DELUXE, new BigDecimal("820.00"),
    72	                RoomType.SUITE, new BigDecimal("1200.00"));
    73	
    74	        @Override
    75	        void validate(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    76	            if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY || !checkOut.equals(checkIn.plusDays(2))) {
    77	                throw invalid("the weekend package is from a Friday to the Sunday right after it");
    78	            }
    79	        }
    80	
    81	        @Override
    82	        Price price(PriceCalculator calculator, Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    83	            BigDecimal packagePrice = cents(prices.get(room.type()));
    84	            return new Price(2, packagePrice, cents(BigDecimal.ZERO), packagePrice);
    85	        }
    86	
    87	        @Override
    88	        BigDecimal refund(BigDecimal amountPaid) {
    89	            return cents(amountPaid.multiply(new BigDecimal("0.5")));
    90	        }
    91	    },
    92	    /** For stays of 7 nights or more: 10% off the nights (high season still applies). Full refund. */
    93	    LONG_STAY {
    94	        @Override
    95	        void validate(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    96	            if (ChronoUnit.DAYS.between(checkIn, checkOut) < 7) {
    97	                throw invalid("the long-stay rate needs at least 7 nights");
    98	            }
    99	        }
   100	
   101	        @Override
   102	        Price price(PriceCalculator calculator, Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
   103	            return discounted(calculator, room, checkIn, checkOut, new BigDecimal("0.10"));
   104	        }
   105	
   106	        @Override
   107	        BigDecimal refund(BigDecimal amountPaid) {
   108	            return amountPaid;
   109	        }
   110	    };
   111	
   112	    /** Throws INVALID_REQUEST if this plan cannot be used for the stay. Most plans have no restriction. */
   113	    void validate(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
   114	    }
   115	
   116	    /** The price of the stay under this plan (the stay has already been validated). */
   117	    abstract Price price(
   118	            PriceCalculator calculator, Room room, LocalDate checkIn, LocalDate checkOut, String companyCode);
   119	
   120	    /** What goes back to the guest who cancels after paying {@code amountPaid}. */
   121	    abstract BigDecimal refund(BigDecimal amountPaid);
   122	
   123	    /** The nights at the usual prices, minus a percentage of their sum. */
   124	    static Price discounted(
   125	            PriceCalculator calculator, Room room, LocalDate checkIn, LocalDate checkOut, BigDecimal percentage) {
   126	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
   127	        BigDecimal subtotal = calculator.sumOfNights(room, checkIn, checkOut);
   128	        BigDecimal discount = cents(subtotal.multiply(percentage));
   129	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
   130	    }
   131	
   132	    private static HotelException invalid(String message) {
   133	        return new HotelException(ErrorCode.INVALID_REQUEST, message);
   134	    }
