    22	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
    23	        return ratePlan.price(this, room, checkIn, checkOut, companyCode);
    24	    }
    25	
    26	    /** The sum of the nights at their usual prices (high season included), before any discount. */
    27	    BigDecimal sumOfNights(Room room, LocalDate checkIn, LocalDate checkOut) {
    28	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    29	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    30	            subtotal = subtotal.add(nightPrice(room, night));
    31	        }
    32	        return subtotal;
    33	    }
    34	
    35	    BigDecimal nightPrice(Room room, LocalDate night) {
    36	        BigDecimal nightlyRate = room.nightlyRate();
    37	        if (isHighSeason(night)) {
    38	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    39	        }
    40	        return cents(nightlyRate);
    41	    }
    42	
    43	    /** High season: from December 15 to the end of February, and the whole of July. */
    44	    static boolean isHighSeason(LocalDate date) {
    45	        Month month = date.getMonth();
    46	        return month == Month.JANUARY
    47	                || month == Month.FEBRUARY
    48	                || month == Month.JULY
    49	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    50	    }
    51	
    52	    static BigDecimal cents(BigDecimal value) {
    53	        return value.setScale(2, RoundingMode.HALF_EVEN);
    54	    }
    55	}
